// The edit's timeline. Every timed element of the composition reads its times from beats.json through these helpers,
// so the user can move and resize it on the app's timeline without asking Claude. Do not edit this file.
import DATA from './beats.json';

export type Beat = {id: string; track: string; label: string; startMs: number; endMs: number};

const LIST: Beat[] = ((DATA as any).beats || []) as Beat[];
const BY_ID = new Map(LIST.map((b) => [b.id, b]));

// the beat with this id; a missing id is a bug in the composition, so it fails loudly in the preview
export const beat = (id: string): Beat => {
  const b = BY_ID.get(id);
  if (!b) throw new Error(`beats.json has no beat "${id}"`);
  return b;
};
// the start and end of a beat, in ms
export const at = (id: string) => beat(id).startMs;
export const until = (id: string) => beat(id).endMs;
// every beat on a track, in time order
export const beatsOn = (track: string): Beat[] => LIST.filter((b) => b.track === track).sort((a, b) => a.startMs - b.startMs);
// the beat of a track that is on screen at ms (or null)
export const activeOn = (track: string, ms: number): Beat | null => beatsOn(track).find((b) => ms >= b.startMs && ms < b.endMs) || null;
export const allBeats = (): Beat[] => [...LIST];
